function buildGraph(n, edges, directed=false) {
  const g = Array.from({length:n}, ()=>[]);
  for (const [u,v] of edges) {
    g[u].push(v);
    if (!directed) g[v].push(u);
  }
  return g;
}

// DFS iterative
function dfs(graph, start, n) {
  const visited = new Array(n).fill(false);
  const stack = [start];
  visited[start] = true; // mark before pushing
  while (stack.length) {
    const node = stack.pop();
    // process node
    for (const nb of graph[node]) {
      if (!visited[nb]) { visited[nb]=true; stack.push(nb); }
    }
  }
}

// BFS — gives shortest distances in unweighted graph
function bfs(graph, start, n) {
  const visited = new Array(n).fill(false);
  const dist = new Array(n).fill(-1);
  const queue = [start];
  visited[start]=true; dist[start]=0;
  let head=0;
  while (head < queue.length) {
    const node = queue[head++];
    for (const nb of graph[node]) {
      if (!visited[nb]) {
        visited[nb]=true;          // mark on enqueue, not dequeue
        dist[nb]=dist[node]+1;
        queue.push(nb);
      }
    }
  }
  return dist;
}

// Count connected components
function countComponents(graph, n) {
  const visited = new Array(n).fill(false);
  let count=0;
  for (let i=0;i<n;i++) {
    if (!visited[i]) { count++; /* run bfs/dfs marking visited */ }
  }
  return count;
}
